(function createInstallationUI(env) {
 'use strict';
 const d=env.document,w=env.window,queue=[],pending=new Set();
 let state=env.state,settingsDialog,shadow,content,welcomeShell,welcome,confirmation,confirmationContent,disposed=false,serial=0,previousFocus,repairDecision;
 const wizardActions=new Set(['choose-theme','choose-toolbar','installation-preferences','welcome-record','bootstrap-retry','repair-resource']);
 function node(tag,text,parent,className){const n=d.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;if(parent)parent.append(n);return n;}
 function button(text,action,parent,accent=false){const n=node('button',text,parent,'button'+(accent?' button--accent':''));n.type='button';n.onclick=action;return n;}
 function request(action,data={}){const requestId='installation-'+(++serial);pending.add(requestId);queue.push({action,...data,requestId});return requestId;}
 function status(text,parent){const n=node('p',text,parent,'installation-status');n.setAttribute('role','status');return n;}
 function field(label,parent){const row=node('label',undefined,parent,'settings-row');node('span','\uE713',row,'settings-row__glyph').setAttribute('aria-hidden','true');node('span',label,row,'settings-row__title');return row;}
 function closeDialog(dialog){if(!dialog)return;if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
 function openDialog(dialog){if(dialog.open)return;if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
 function themeMode(){return env.themeMode&&String(env.themeMode()).toLowerCase()==='dark'?'dark':'light';}
 function tokens(element,applyMode=true){
  if(applyMode)element.setAttribute('data-theme',themeMode());
  const keys=['light3','light2','light1','','dark1','dark2','dark3'];
  if(Array.isArray(state.accent)&&state.accent.length===7)state.accent.forEach((color,i)=>{if(/^#[0-9a-f]{6}$/i.test(color))element.style.setProperty('--win-accent'+(keys[i]?'-'+keys[i]:''),color);});
 }
 function syncTheme(){syncFrame();if(shadow)tokens(shadow.host);if(welcomeShell)tokens(welcomeShell);if(confirmationContent)tokens(confirmationContent.getRootNode().host);}
 function modal(className){const dialog=node('dialog',undefined,d.body,className);dialog.addEventListener('keydown',e=>e.stopPropagation());return dialog;}
 function shadowView(dialog){const host=node('div',undefined,dialog),root=host.attachShadow({mode:'open'}),style=node('style',undefined,root);style.textContent=env.styles.replace(/:root/g,':host');return {root,main:node('main',undefined,root,'installation-content')};}
 function confirmRepair(resource,fromWizard=false){
  if(!['updater','themeDark','themeLight'].includes(resource.id))throw Error('Unsupported resource repair.');
  if(!confirmation){confirmation=modal('tbUI3-installation-dialog');confirmation.setAttribute('aria-label','Confirm resource reset');confirmationContent=shadowView(confirmation).main;confirmation.addEventListener('cancel',()=>{if(repairDecision){repairDecision(false);repairDecision=null;}});}
  confirmationContent.replaceChildren();node('h1','Back up and reset this resource?',confirmationContent);node('p',resource.path||resource.id,confirmationContent,'installation-path');
  node('p','This replaces the customized file with the verified bundled copy after retaining a verified backup. A newer updater will never be downgraded. Your selected IDE theme will stay unchanged.',confirmationContent);
  const row=field('I approve keeping a backup and resetting this file',confirmationContent),approve=node('input',undefined,row);approve.type='checkbox';
  const actions=node('footer',undefined,confirmationContent,'installation-actions');const settle=approved=>{closeDialog(confirmation);welcomeShell?.querySelector('iframe')?.focus();if(repairDecision){repairDecision(approved);repairDecision=null;}else if(approved)request('repair-resource',{id:resource.id,confirmed:true});};
  button('Cancel',()=>settle(false),actions);
  const reset=button('Back up and reset',()=>settle(true),actions,true);reset.disabled=true;approve.onchange=()=>{reset.disabled=!approve.checked;};
  tokens(confirmationContent.getRootNode().host);openDialog(confirmation);approve.focus();if(fromWizard)return new Promise(resolve=>{repairDecision=resolve;});return false;
 }
 function wizardSnapshot(next){
  const original=next.bootstrap||{},statuses={'provisioned':'installed','customized-preserved':'modified','blocked':'error','newer-preserved':'installed'};
  const bootstrap={...original,status:['attention','busy'].includes(original.status)?'warning':original.status,
   resources:(original.resources||[]).map(resource=>({...resource,status:statuses[resource.status]||resource.status}))};
  if(next.themeDiscovery?.error){
   if(bootstrap.status!=='error')bootstrap.status='warning';
   bootstrap.message=(bootstrap.message||'')+' Theme discovery needs attention: '+next.themeDiscovery.error+' Use Check again to retry.';
  }
  return {...next,bootstrap};
 }
 function ensureWelcome(){
  if(welcome)return;
  if(typeof w.tbUI3CreateWelcomeWizard!=='function')throw Error('The embedded Welcome Wizard is unavailable.');
  welcomeShell=modal('tbUI3-welcome-shell');welcomeShell.setAttribute('aria-label','Welcome to tbUI3IDE');
  welcome=w.tbUI3CreateWelcomeWizard({document:d,mount:welcomeShell,assets:{masterCss:env.welcomeMaster,controlsJs:env.welcomeControls,welcomeCss:env.welcomeStyles},source:'native-addin',
   send:message=>{if(!message||!wizardActions.has(message.action))throw Error('Unsupported wizard operation.');const {action,...data}=message;if(action==='choose-theme')welcome.setPreviewMode(null);request(action,data);},
   confirmRepair:resource=>confirmRepair(resource,true),
   onClose:()=>{closeDialog(welcomeShell);if(previousFocus&&previousFocus.isConnected)previousFocus.focus();}
  });
  welcomeShell.addEventListener('cancel',e=>{e.preventDefault();request('welcome-record',{schema:1,disposition:'dismissed'});welcome.close();});
 }
 function showWelcome(){
  if(settingsDialog)closeDialog(settingsDialog);
  ensureWelcome();previousFocus=d.activeElement;tokens(welcomeShell);openDialog(welcomeShell);welcome.open(wizardSnapshot(state));watchFrame();
 }
 function syncFrame(){
  const frame=welcomeShell?.querySelector('iframe'),inner=frame?.contentDocument;if(!inner)return;
  // The Wizard owns its preview mode; apply only the system accent here.
  tokens(inner.documentElement,false);
 }
 function watchFrame(){
  const frame=welcomeShell.querySelector('iframe');if(!frame||frame.dataset.nativeWatched)return;
  frame.dataset.nativeWatched='true';frame.addEventListener('load',()=>{
   if(disposed)return;
   if(!frame.contentWindow?.WinUIControls){
    frame.hidden=true;const view=shadowView(welcomeShell);tokens(view.root.host);node('h1','Welcome controls unavailable',view.main);const alert=node('p','The IDE could not initialize the embedded iframe runtime. Close this dialog and inspect the IDE Debug Console.',view.main);alert.setAttribute('role','alert');button('Close',()=>welcome.close(),view.main);return;
   }
   syncFrame();frame.focus();
  },{once:true});
 }
 function preferences(parent){
  if(state.settingsError){
   status('Stored settings are unavailable and were preserved: '+state.settingsError,parent);
   const row=field('Back up and reset these installation preferences',parent),approve=node('input',undefined,row);approve.type='checkbox';
   const reset=button('Back up and reset preferences',()=>request('reset-installation-settings',{confirmed:true}),parent);reset.disabled=true;approve.onchange=()=>{reset.disabled=!approve.checked;};return;
  }
  const autoRow=field('Check for updates once a day for this IDE',parent),auto=node('input',undefined,autoRow);auto.type='checkbox';auto.checked=state.preferences.automatic;auto.dataset.focusKey='automatic';auto.onchange=()=>request('installation-preferences',{automatic:auto.checked});
  const restartRow=field('Restart this IDE after a successful update',parent),restart=node('input',undefined,restartRow);restart.type='checkbox';restart.checked=state.preferences.restart;restart.dataset.focusKey='restart';restart.onchange=()=>request('installation-preferences',{restart:restart.checked});
 }
 function renderSettings(){
  if(!content)return;
  const active=shadow.activeElement,key=active?.dataset.focusKey;
  content.replaceChildren();const title=node('h1','tbUI3 installations',content);title.tabIndex=-1;
  node('p','Preferences, approvals and recovery below belong only to this IDE. The per-user add-in, updater and themes are shared.',content);
  node('p',state.root,content,'installation-path');node('p','Installation ID: '+state.installationId,content,'installation-path');
  node('p','IDE update strategy: In-place (recommended)',content);preferences(content);
  node('p','Downloads and installation require approval. Update Now follows normal save prompts; Update on Exit waits for an accepted shutdown.',content);
  node('h2','Bundled updater and themes',content);status(state.bootstrap?.message||'No provisioning status is available.',content);
  if(state.bootstrap?.ledgerError){
   status('The resource registry was preserved: '+state.bootstrap.ledgerError,content);
   const row=field('Back up and reset the shared resource registry; preserve customized files',content),approve=node('input',undefined,row);approve.type='checkbox';
   const reset=button('Back up and reset resource registry',()=>request('reset-shared-resource-ledger',{confirmed:true}),content);reset.disabled=true;approve.onchange=()=>{reset.disabled=!approve.checked;};
  }
  if(state.bootstrap?.ledgerBackup)node('p','Resource registry backup: '+state.bootstrap.ledgerBackup,content,'installation-path');
  for(const resource of state.bootstrap?.resources||[]){
   const row=node('section',undefined,content,'card');node('h3',({updater:'Updater',themeDark:'WinUI3 Dark',themeLight:'WinUI3 Light'})[resource.id]||resource.id,row);node('p',resource.message||resource.status,row);node('p',resource.path,row,'installation-path');
   if(resource.backup)node('p','Backup: '+resource.backup,row,'installation-path');
   if(resource.repairable)button('Review reset and backup',()=>confirmRepair(resource),row);
  }
  if(state.themeDiscovery?.error)status('Theme discovery: '+state.themeDiscovery.error,content);
  button('Recheck and repair missing resources',()=>request('bootstrap-retry'),content);
  if(state.recovery){status('An unfinished transaction needs recovery. It will wait for IDE processes to close normally.',content);button('Open recovery',()=>request('open-recovery'),content);}
  if(state.message)status(state.message,content);
  const footer=node('footer',undefined,content,'installation-actions');button('Welcome to tbUI3IDE',showWelcome,footer);button('Close',()=>closeDialog(settingsDialog),footer);
  if(key){const next=shadow.querySelector('[data-focus-key='+JSON.stringify(key)+']');if(next)next.focus();}
 }
 function showSettings(){
  if(welcome)welcome.close();
  if(!settingsDialog){settingsDialog=modal('tbUI3-installation-dialog');settingsDialog.setAttribute('aria-label','tbUI3 installation settings and repair');const view=shadowView(settingsDialog);shadow=view.root;content=view.main;}
  renderSettings();syncTheme();openDialog(settingsDialog);shadow.querySelector('h1').focus();
 }
 function attach(){
  for(const name of d.querySelectorAll('.tbis-optionName')){
   if(name.textContent.trim()!=='Colour Theme')continue;
   const anchor=name.closest('.tbis-optionRow');if(!anchor||anchor.parentElement.querySelector('.tbUI3InstallationOptions'))continue;
   const row=node('div',undefined,undefined,'tbis-optionRow tbUI3InstallationOptions tbUI3OptionActions');node('div','tbUI3 installations',row,'tbis-optionLabelCol');const col=node('div',undefined,row,'tbis-optionValueCol');button('Settings and repair',showSettings,col);button('Welcome to tbUI3IDE',showWelcome,col);anchor.after(row);
  }
 }
 const style=node('style',undefined,d.head);style.textContent=env.dialogStyles;
 attach();const observer=new w.MutationObserver(attach);observer.observe(d.body,{childList:true,subtree:true});
 const themeObserver=new w.MutationObserver(syncTheme);themeObserver.observe(d.documentElement,{attributes:true,attributeFilter:['class','style','data-theme']});
 if(env.showWelcome&&env.canAutoWelcome?.()&&!disposed)showWelcome();
 return {show:which=>which==='welcome'?showWelcome():showSettings(),hide:()=>{if(welcome)welcome.close();closeDialog(settingsDialog);},
  take:()=>{const next=queue.shift();return next?JSON.stringify(next):'';},
  publish:next=>{state=next;if(next.ack?.id)pending.delete(next.ack.id);renderSettings();syncTheme();if(welcome&&pending.size===0){welcome.setSnapshot(wizardSnapshot(next));syncFrame();if(welcome.getState().open&&!confirmation?.open&&!welcomeShell.contains(d.activeElement))welcomeShell.querySelector('iframe')?.focus();}},
  dispose:()=>{disposed=true;if(repairDecision){repairDecision(false);repairDecision=null;}observer.disconnect();themeObserver.disconnect();if(welcome)welcome.destroy();for(const dialog of[welcomeShell,settingsDialog,confirmation])if(dialog)dialog.remove();style.remove();d.querySelectorAll('.tbUI3InstallationOptions').forEach(n=>n.remove());}
 };
})

/* Native HTML dialog modality and geometry; view/control styles are scoped separately. */
.tbUI3-installation-dialog { padding:0; width:min(760px,calc(100vw - 48px)); max-height:86vh; border:0; border-radius:8px; background:Canvas; color:CanvasText; }
.tbUI3-installation-dialog::backdrop { background:color-mix(in srgb,CanvasText 35%,transparent); }
.tbUI3-welcome-shell { box-sizing:border-box; width:min(1080px,calc(100vw - 48px)); max-width:calc(100vw - 48px); height:min(760px,calc(100vh - 48px)); max-height:calc(100vh - 48px); padding:0; margin:auto; border:0; border-radius:8px; background:Canvas; color:CanvasText; overflow:hidden; }
.tbUI3-welcome-shell::backdrop { background:rgba(0,0,0,.40); }

import fs from 'node:fs';import vm from 'node:vm';import test from 'node:test';import assert from 'node:assert/strict';
const {JSDOM,VirtualConsole}=await import(process.env.TB_JSDOM_MODULE||'jsdom');
const factory=vm.runInNewContext(fs.readFileSync('tbIDE/tbUI3IDE/js/installation-ui.js','utf8'));
const asset=name=>fs.readFileSync('tbIDE/prototypes/welcome-wizard/'+name,'utf8');
const tick=()=>new Promise(resolve=>setTimeout(resolve,0));
function fixture(options={}){
 const errors=[],virtualConsole=new VirtualConsole();virtualConsole.on('jsdomError',e=>{if(!/Could not parse CSS stylesheet/.test(e.message))errors.push(e);});
 const dom=new JSDOM('<!doctype html><html><head></head><body><button id="before">Before</button><div class="tbis-optionRow"><div class="tbis-optionName">Colour Theme</div></div></body></html>',{runScripts:'dangerously',virtualConsole});
 const w=dom.window,d=w.document;
 w.HTMLDialogElement.prototype.showModal=function(){this.setAttribute('open','');};w.HTMLDialogElement.prototype.close=function(){this.removeAttribute('open');};
 // JSDOM lacks browser media APIs. Shared runtime is real, not stubbed or replaced.
 d.addEventListener('load',e=>{if(e.target.localName==='iframe'){const child=e.target.contentWindow;child.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){},addListener(){},removeListener(){}});}},true);
 w.eval(asset('welcome.js'));
 const palette={background:'#111111',surface:'#222222',foreground:'#eeeeee',accent:'#123456',toolbar:'#333333',editor:'#444444'};
 let state={schema:1,root:'C:\\IDE <img src=x>',installationId:'v1-test',theme:'WinUI3 Light',toolbar:'Classic',preferences:{automatic:true,restart:false,channel:'development',strategy:'InPlace'},bootstrap:{status:'ready',message:'Resources verified.',resources:[]},installedThemes:[{name:'WinUI3 Light',mode:'light',preview:palette},{name:'WinUI3 Dark',mode:'dark',preview:palette},{name:'Ocean',mode:'dark',preview:palette}],accent:['#010101','#020202','#030303','#040404','#050505','#060606','#070707']};
 const ui=factory({document:d,window:w,state,styles:':root{--test:1}',dialogStyles:'.tbUI3-installation-dialog{margin:auto}',welcomeStyles:asset('welcome.css'),welcomeMaster:asset('master.css'),welcomeControls:options.controls??asset('controls.js'),themeMode:()=>'Dark',showWelcome:!!options.auto,canAutoWelcome:options.canAutoWelcome});
 const shadow=()=>d.querySelector('.tbUI3-installation-dialog[open] div')?.shadowRoot;
 const inner=()=>d.querySelector('iframe')?.contentDocument;
 function click(text,root=inner()||d){const n=[...root.querySelectorAll('button')].find(n=>n.textContent.trim()===text||n.getAttribute('aria-label')===text);assert(n,'button '+text);n.click();return n;}
 function publish(patch,ack){state={...state,...patch,...(ack?{ack:{id:ack.requestId,ok:!patch.message?.startsWith('Error')}}:{})};ui.publish(state);}
 async function open(){ui.show('welcome');for(let i=0;i<10&&!inner()?.querySelector('.welcome-app');i++)await tick();assert(inner()?.querySelector('.welcome-app'),'real shared Toolkit initialized inside iframe');assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'));}
 return {w,d,ui,click,shadow,inner,open,publish,take:()=>JSON.parse(ui.take()||'null'),dispose(){ui.dispose();w.close();}};
}
test('settings are scoped, safe and omit release channel UI',()=>{const f=fixture();try{f.ui.show('settings');const s=f.shadow();assert.match(s.textContent,/In-place \(recommended\)/);assert.equal(s.querySelector('img'),null);assert.equal(s.querySelector('select'),null);assert(!s.textContent.includes('release channel'));assert.match(s.querySelector('style').textContent,/:host/);assert.equal(f.d.documentElement.style.getPropertyValue('--win-accent'),'');assert.equal(s.host.style.getPropertyValue('--win-accent'),'#040404');}finally{f.dispose();}});
test('preferences are correlated and native rejection restores actual values',()=>{const f=fixture();try{f.ui.show('settings');f.shadow().querySelector('input').click();const r=f.take();assert.equal(r.action,'installation-preferences');assert.equal(r.automatic,false);f.publish({preferences:{automatic:true,restart:false},message:'Error: refused'},r);assert(f.shadow().querySelector('input').checked);}finally{f.dispose();}});
test('real Toolkit stays inside iframe; healthy wizard has six steps and explicit Finish',async()=>{const f=fixture();try{await f.open();assert(f.inner().defaultView.WinUIControls);assert.equal(f.w.WinUIControls,undefined);assert.equal(f.d.querySelector('winui-button'),null);assert.equal(f.inner().documentElement.style.getPropertyValue('--win-accent'),'#040404');for(const title of ['Make twinBASIC your own','Updates on your terms','Choose your appearance','Choose your toolbar','Explore your new tools',"You're ready"]){assert(f.inner().querySelector('h2').textContent.includes(title),f.inner().querySelector('h2').textContent);assert.equal(f.take(),null);if(title!=="You're ready")f.click('Continue');}f.click('Finish');assert.equal(f.take().disposition,'completed');assert.equal(f.d.querySelector('.tbUI3-welcome-shell').open,false);}finally{f.dispose();}});
test('installed theme tile selection and native rejection reconcile with actual state',async()=>{const f=fixture();try{await f.open();f.click('Continue');f.click('Continue');assert.equal(f.take(),null);const ocean=f.click('Select Ocean theme');assert.equal(ocean.style.getPropertyValue('--mini-bg'),'');assert.equal(ocean.querySelector('.welcome-mini-ide').style.getPropertyValue('--mini-bg'),'#111111');const r=f.take();assert.equal(r.name,'Ocean');assert.equal(r.action,'choose-theme');assert(f.inner().querySelector('[aria-label="Select Ocean theme"]').disabled);f.publish({theme:'WinUI3 Light',message:'Error: rejected'},r);assert.equal(f.inner().querySelector('[aria-label="Select WinUI3 Light theme"]').getAttribute('aria-pressed'),'true');assert.equal(f.inner().querySelector('[aria-label="Select Ocean theme"]').getAttribute('aria-pressed'),'false');}finally{f.dispose();}});
test('unrelated snapshots do not settle pending wizard settings',async()=>{const f=fixture();try{await f.open();f.click('Continue');const toggle=f.inner().querySelector('winui-toggle-switch');toggle.dispatchEvent(new (f.inner().defaultView.CustomEvent)('toggled',{detail:{isOn:false}}));const r=f.take();assert.equal(r.automatic,false);f.publish({message:'background'});assert(f.inner().querySelector('winui-toggle-switch').hasAttribute('disabled'));f.publish({preferences:{automatic:false,restart:false}},r);assert(!f.inner().querySelector('winui-toggle-switch').hasAttribute('disabled'));}finally{f.dispose();}});
test('Setup exists only for actual attention and clears into Updates',async()=>{const f=fixture();try{f.publish({bootstrap:{status:'error',message:'Helper unavailable',resources:[]}});await f.open();f.click('Continue');assert.match(f.inner().querySelector('h2').textContent,/Installation needs attention/);f.click('Check again');const r=f.take();assert.equal(r.action,'bootstrap-retry');f.publish({bootstrap:{status:'ready',message:'Verified',resources:[]}},r);assert.match(f.inner().querySelector('h2').textContent,/Updates/);assert(!f.inner().querySelector('nav').textContent.includes('Setup'));}finally{f.dispose();}});
async function repairFixture(){const f=fixture();f.publish({bootstrap:{status:'attention',message:'Customized',resources:[{id:'themeDark',path:'C:\\Theme',status:'customized-preserved',repairable:true}]}});await f.open();f.click('Continue');return f;}
test('iframe repair awaits outer styled confirmation and checked approval',async()=>{const f=await repairFixture();try{f.click('Repair');await tick();assert.equal(f.take(),null);const s=f.shadow();assert(s);const reset=[...s.querySelectorAll('button')].find(n=>n.textContent==='Back up and reset');assert(reset.disabled);s.querySelector('input').click();reset.click();await tick();const r=f.take();assert.equal(r.action,'repair-resource');assert.equal(r.id,'themeDark');assert(r.confirmed);assert.equal(f.take(),null);}finally{f.dispose();}});
test('cancelled repair issues no native request',async()=>{const f=await repairFixture();try{f.click('Repair');await tick();f.click('Cancel',f.shadow());await tick();assert.equal(f.take(),null);}finally{f.dispose();}});
test('Escape inside iframe dismisses; reopen and disposal keep one options entry',async()=>{const f=fixture();try{await f.open();f.inner().dispatchEvent(new (f.inner().defaultView.KeyboardEvent)('keydown',{key:'Escape',bubbles:true,cancelable:true}));assert.equal(f.take().disposition,'dismissed');assert.equal(f.d.querySelector('.tbUI3-welcome-shell').open,false);await f.open();assert.equal(f.d.querySelectorAll('iframe').length,1);f.d.body.append(f.d.createElement('span'));await tick();assert.equal(f.d.querySelectorAll('.tbUI3InstallationOptions').length,1);f.ui.dispose();assert.equal(f.d.querySelectorAll('iframe,dialog,style,.tbUI3InstallationOptions').length,0);}finally{f.dispose();}});
test('future settings expose explicit backed-up reset only',()=>{const f=fixture();try{f.ui.show('settings');f.publish({settingsError:'Future schema 99'});const s=f.shadow(),reset=[...s.querySelectorAll('button')].find(n=>n.textContent==='Back up and reset preferences');assert(reset.disabled);s.querySelector('input').click();reset.click();assert.equal(f.take().action,'reset-installation-settings');}finally{f.dispose();}});

test('theme discovery errors have a recoverable conditional Setup step',async()=>{const f=fixture();try{f.publish({themeDiscovery:{pending:false,error:'Theme reload failed'}});await f.open();f.click('Continue');assert.match(f.inner().querySelector('h2').textContent,/Installation needs attention/);assert.match(f.inner().body.textContent,/Theme reload failed/);f.click('Check again');assert.equal(f.take().action,'bootstrap-retry');}finally{f.dispose();}});
test('blocked iframe runtime surfaces a visible scoped error with Close',async()=>{const f=fixture({controls:'/* deliberately unavailable runtime for failure-path test */'});try{f.ui.show('welcome');await tick();await tick();const shell=f.d.querySelector('.tbUI3-welcome-shell'),root=shell.querySelector('div')?.shadowRoot;assert(root);assert.match(root.textContent,/Welcome controls unavailable/);assert(shell.querySelector('iframe').hidden);f.click('Close',root);assert.equal(shell.open,false);}finally{f.dispose();}});

test('late startup does not take focus or persist Welcome completion',()=>{const f=fixture({auto:true,canAutoWelcome:()=>false});try{assert.equal(f.d.querySelector('.tbUI3-welcome-shell'),null);assert.equal(f.take(),null);}finally{f.dispose();}});
test('lowercase native theme acknowledgement retains the selected tile and toolbar palette',async()=>{const f=fixture();try{await f.open();f.click('Continue');f.click('Continue');f.click('Select Ocean theme');const r=f.take();f.publish({theme:'ocean',themeMode:'dark',message:'IDE theme saved.'},r);const selected=f.inner().querySelector('[aria-label="Select Ocean theme"]');assert.equal(selected.getAttribute('aria-pressed'),'true');assert.equal(selected.querySelector('.welcome-mini-ide').style.getPropertyValue('--mini-bg'),'#111111');f.click('Continue');assert.equal(f.inner().querySelectorAll('.welcome-mini-ide').length,3);assert.equal(f.inner().querySelectorAll('.welcome-preview-empty').length,0);}finally{f.dispose();}});
test('all miniature paint remains fixed when the active theme changes',async()=>{const f=fixture();try{await f.open();f.click('Continue');f.click('Continue');const read=()=>[...f.inner().querySelectorAll('.welcome-mini-ide')].map(e=>e.getAttribute('style'));const before=read();f.publish({theme:'ocean',themeMode:'dark'});assert.deepEqual(read(),before);}finally{f.dispose();}});
